import { Component, Event, EventEmitter, h, Prop } from '@stencil/core';

@Component({
  tag: 'std-upload-loader',
  styleUrl: 'std-upload-loader.css',
  shadow: true
})
export class StdUploadLoaderComponent {
  @Prop() classes: string;
  @Prop() nameFile: string;
  @Prop() textStatus: string;
  @Prop() status: string = 'loading';
  @Prop() progress: string;
  @Prop() disabled: boolean = false;

  @Event()
  cancelFlow: EventEmitter;

  onClickCancel(event: Event): void {
    this.cancelFlow.emit(event);
  }

  render() {
    const defaulMessage = {
      loading: 'Cargando...',
      success: 'Carga exitosa',
      error: 'Carga fallida. Intenta cargar el archivo nuevamente.'
    }[this.status];

    const uploadClasses = ['css-upload-loader shadow-button p-4 flex justify-between items-center gap-4', this.classes, this.disabled ? 'disabled' : '']
      .join(' ')
      .trim()
      .replace(/\s+/g, ' ');

    return (
      <div class={uploadClasses}>
        <div class="flex-1 flex items-center gap-4">
          {this.status === 'loading' && !this.progress && (
            <svg class="animate-svg" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
              <circle class="opacity-25" cx="12" cy="12" r="10" stroke="#e80000" stroke-width="4"></circle>
              <path class="opacity-75" fill="#e80000" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
            </svg>
          )}
          {this.status === 'loading' && this.progress && <std-small-rounded-progress progress={this.progress.toString()}></std-small-rounded-progress>}
          {this.status === 'success' && !this.disabled && <std-support-icons type="success" class="w-6 h-6 "></std-support-icons>}
          {this.status === 'success' && this.disabled && <i class="icon-checkmark-in-a-circle text-2xl text-labeldisabled" />}
          {this.status === 'error' && <std-support-icons type="error" class="w-6 h-6"></std-support-icons>}
          <div class="flex-1 flex flex-col gap-1">
            <p class={`text-sm font-bold css-upload-loader-text `}>{this.nameFile}</p>
            <p class={`text-sm css-upload-loader-text  ${this.status === 'error' ? 'text-error' : ''}`}>{this.textStatus || defaulMessage}</p>
          </div>
          <button onClick={e => this.onClickCancel(e)} class="shrink-0 leading-none">
            <i class="icon-close text-2xl leading-none"></i>
          </button>
        </div>
      </div>
    );
  }
}
